'use strict';

const _ = require('lodash');
const BbPromise = require('bluebird');

module.exports = {
  compileDeployment() {
    this.apiGatewayDeploymentLogicalId = this.provider.naming
      .generateApiGatewayDeploymentLogicalId();

    const customResources = _.get(this.serverless.service, 'resources.Resources', {});
    _.forEach(customResources, (resource) => {
      const restApiId = _.get(resource, 'Properties.RestApiId');
      if (resource.Type !== 'AWS::ApiGateway::BasePathMapping'
        || !_.isEqual(restApiId, this.provider.getApiGatewayRestApiId())) {
        return;
      }

      const dependencies = [].concat(resource.DependsOn || []);
      if (!_.includes(dependencies, this.apiGatewayDeploymentLogicalId)) {
        dependencies.push(this.apiGatewayDeploymentLogicalId);
      }
      resource.DependsOn = dependencies.length === 1 ? dependencies[0] : dependencies;
    });

    _.merge(this.serverless.service.provider.compiledCloudFormationTemplate.Resources, {
      [this.apiGatewayDeploymentLogicalId]: {
        Type: 'AWS::ApiGateway::Deployment',
        Properties: {
          RestApiId: this.provider.getApiGatewayRestApiId(),
          StageName: this.provider.getStage(),
          Description: this.provider.getApiGatewayDescription(),
        },
        DependsOn: this.apiGatewayMethodLogicalIds,
      },
    });

    // create CLF Output for endpoint
    _.merge(this.serverless.service.provider.compiledCloudFormationTemplate.Outputs, {
      ServiceEndpoint: {
        Description: 'URL of the service endpoint',
        Value: {
          'Fn::Join': ['',
            [
              'https://',
              this.provider.getApiGatewayRestApiId(),
              `.execute-api.${this.provider.getRegion()}.`,
              { Ref: 'AWS::URLSuffix' },
              `/${this.provider.getStage()}`,
