            Ref: awsCompileApigEvents.apiGatewayRestApiLogicalId,
          },
          Description: undefined,
          StageName: 'dev',
        },
      });
    })
  );

  it('should create a deployment resource with description', () => {
    awsCompileApigEvents.serverless.service.provider.apiGateway = {
      description: 'Some Description',
    };

    return awsCompileApigEvents
      .compileDeployment().then(() => {
        const apiGatewayDeploymentLogicalId = Object
          .keys(awsCompileApigEvents.serverless.service.provider
              .compiledCloudFormationTemplate.Resources)[0];

        expect(
            awsCompileApigEvents.serverless.service.provider.compiledCloudFormationTemplate
              .Resources[apiGatewayDeploymentLogicalId]
          ).to.deep.equal({
            Type: 'AWS::ApiGateway::Deployment',
            DependsOn: ['method-dependency1', 'method-dependency2'],
            Properties: {
              RestApiId: {
                Ref: awsCompileApigEvents.apiGatewayRestApiLogicalId,
              },
              Description: 'Some Description',
              StageName: 'dev',
            },
          });
      });
  }
  );

  it('should make custom API Gateway base path mappings depend on deployment', () => {
    serverless.service.resources = {
      Resources: {
        BasePathMapping: {
          Type: 'AWS::ApiGateway::BasePathMapping',
          Properties: { RestApiId: { Ref: 'ApiGatewayRestApi' } },
        },
        CustomBasePathMapping: {
          Type: 'AWS::ApiGateway::BasePathMapping',
          DependsOn: ['CustomDependency'],
          Properties: { RestApiId: { Ref: 'ApiGatewayRestApi' } },
        },
        UnrelatedApiBasePathMapping: {
          Type: 'AWS::ApiGateway::BasePathMapping',
          Properties: { RestApiId: { Ref: 'AnotherApi' } },
        },
        UnrelatedResource: {
          Type: 'AWS::S3::Bucket',
          Properties: {},
        },
      },
    };

    return awsCompileApigEvents.compileDeployment().then(() => {
      const deploymentId = awsCompileApigEvents.apiGatewayDeploymentLogicalId;
      const resources = serverless.service.resources.Resources;
      expect(resources.BasePathMapping.DependsOn).to.equal(deploymentId);
      expect(resources.CustomBasePathMapping.DependsOn)
        .to.deep.equal(['CustomDependency', deploymentId]);
      expect(resources.UnrelatedApiBasePathMapping.DependsOn).to.equal(undefined);
      expect(resources.UnrelatedResource.DependsOn).to.equal(undefined);
    });
  });

  it('should add service endpoint output', () =>
    awsCompileApigEvents.compileDeployment().then(() => {
      expect(
        awsCompileApigEvents.serverless.service.provider.compiledCloudFormationTemplate
          .Outputs.ServiceEndpoint
      ).to.deep.equal({
        Description: 'URL of the service endpoint',
        Value: {
          'Fn::Join': [
            '',
            [
              'https://',
              { Ref: awsCompileApigEvents.apiGatewayRestApiLogicalId },
              '.execute-api.us-east-1.',
              { Ref: 'AWS::URLSuffix' },
              '/dev',
            ],
          ],
        },
      });
    })
  );
});
